<?php
class Jadwal { private $pdo; public function __construct($pdo){$this->pdo=$pdo;} public function all(){return $this->pdo->query('SELECT j.*,f.judul FROM jadwal j JOIN film f ON f.id=j.film_id ORDER BY j.tanggal,j.jam_mulai')->fetchAll();} public function find($id){$s=$this->pdo->prepare('SELECT * FROM jadwal WHERE id=?');$s->execute([$id]);return $s->fetch();} public function save($d){$s=$this->pdo->prepare('INSERT INTO jadwal(film_id,studio,tanggal,jam_mulai,harga,kapasitas) VALUES(?,?,?,?,?,?)');return $s->execute([$d['film_id'],$d['studio'],$d['tanggal'],$d['jam_mulai'],$d['harga'],$d['kapasitas']]);} public function delete($id){$s=$this->pdo->prepare('DELETE FROM jadwal WHERE id=?');$s->execute([$id]);return $s->rowCount();} public function availableSeats($id){$s=$this->pdo->prepare('SELECT j.kapasitas-COALESCE(SUM(b.jumlah_kursi),0) sisa FROM jadwal j LEFT JOIN booking b ON b.jadwal_id=j.id AND b.status="aktif" WHERE j.id=? GROUP BY j.id');$s->execute([$id]);return (int)($s->fetch()['sisa']??0);}}
?>
